import csv
from io import StringIO

def totals_by_payment(csv_text: str) -> dict[str, int]:
    totals: dict[str, int] = {}
    if not csv_text or not csv_text.strip():
        return totals
    reader = csv.DictReader(StringIO(csv_text.lstrip('\ufeff')))
    for row in reader:
        payment = (row.get('payment') or '').strip().lower()
        raw_price = (row.get('price') or '').strip()
        if not payment or not raw_price:
            continue
        price = int(raw_price.replace(',', ''))
        totals[payment] = totals.get(payment, 0) + price
    return totals

import time

def retry(fn, attempts=3, exceptions=(Exception,), sleep=time.sleep, base_delay=1.0):
    if attempts < 1:
        raise ValueError("attempts must be at least 1")
    for i in range(attempts):
        try:
            return fn()
        except exceptions:
            if i == attempts - 1:
                raise
            sleep(base_delay * (2 ** i))

